    <input type="hidden" name="csrf_token" value="<?php echo e($csrfToken); ?>"><input type="hidden" name="idempotency_key" value="<?php echo e(createIdempotencyToken()); ?>"><input type="hidden" name="action" value="create"><input type="hidden" name="return_to" value="purchase_create">
    <section class="purchase-method-card" aria-labelledby="purchaseMethodTitle"><div class="purchase-method-heading"><div><span>Step 1</span><h2 id="purchaseMethodTitle">Choose a purchase method</h2><p>Select the workflow that matches how this supplier purchase should be handled.</p></div><strong id="purchaseMethodStatus">Selection required</strong></div><div class="purchase-method-options">
      <label class="purchase-method-option <?php echo $canReceivePurchase?'':'is-unavailable'; ?>"><input type="radio" name="purchase_type" value="DIRECT" required onchange="syncPurchaseType()" <?php echo $canReceivePurchase?'':'disabled'; ?>><span class="purchase-method-icon direct-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 7h16v12H4zM7 4h10l3 3H4l3-3Zm1 8h8m-4-4v8"/></svg></span><span class="purchase-method-copy"><strong>Direct Purchase</strong><small>Create and receive the purchase in one step. Stock becomes available immediately after saving.</small><em>Save purchase &rarr; Stock received automatically</em><?php if(!$canReceivePurchase):?><b>Receiving permission is required.</b><?php endif;?></span><span class="purchase-method-check" aria-hidden="true">&#10003;</span></label>
      <label class="purchase-method-option"><input type="radio" name="purchase_type" value="PURCHASE_ORDER" required onchange="syncPurchaseType()"><span class="purchase-method-icon order-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M6 3h9l3 3v15H6V3Zm9 0v4h3M9 11h6m-6 4h6"/></svg></span><span class="purchase-method-copy"><strong>Purchase Order</strong><small>Create a draft supplier order first. Mark it as ordered and complete receiving separately later.</small><em>Create order &rarr; Approve &rarr; Receive later</em></span><span class="purchase-method-check" aria-hidden="true">&#10003;</span></label>
    </div></section>
