      <div class="purchase-form-main">
        <section class="purchase-form-card"><div class="purchase-form-section-head"><div><h2 id="purchaseInformationTitle">Purchase Information</h2><p id="purchaseInformationDescription">Supplier, delivery location, and purchase reference.</p></div><span>Required</span></div><div class="purchase-form-grid"><label><span id="purchaseNumberLabel">Purchase Number</span><input name="purchase_number" id="purchaseNumber" data-sequence="<?php echo e($localNow->format('YmdHis')); ?>" placeholder="Choose a purchase method first" required></label><label>Purchase Date<input type="datetime-local" name="purchase_date" value="<?php echo e($localNow->format('Y-m-d\TH:i')); ?>" required></label><label>Supplier<select name="supplier_id" required><option value="">Select supplier</option><?php foreach($suppliers as $supplier):?><option value="<?php echo (int)$supplier['id']; ?>"><?php echo e($supplier['name'].' · '.$supplier['supplier_code']); ?></option><?php endforeach;?></select></label><label>Delivery Location<select name="location_id" required><option value="">Select location</option><?php foreach($locations as $location):?><option value="<?php echo (int)$location['id']; ?>"><?php echo e($location['name'].' · '.$location['code']); ?></option><?php endforeach;?></select></label><label class="purchase-wide-field">Purchase Notes<textarea name="notes" rows="3" maxlength="2000" placeholder="Optional instructions or notes about this purchase"></textarea></label></div></section>

        <section class="purchase-form-card"><div class="purchase-form-section-head"><div><h2>Purchased Products</h2><p>Add every product, quantity, cost, selling price, and expiry when applicable.</p></div><button type="button" class="purchase-form-button purchase-form-button-secondary" onclick="addPurchaseItem()">Add Product</button></div><div class="purchase-item-labels"><span>Product</span><span>Quantity</span><span>Unit Cost</span><span>Sale Price</span><span>Expiry</span><span></span></div><div id="purchaseItemRows" class="purchase-item-rows"></div><div class="purchase-form-total"><span>Purchase Total</span><strong id="purchaseTotal">0.00 <?php echo e($currency); ?></strong></div></section>
