dow:0 5px 14px rgba(37,99,235,.2)}.purchase-form-button-primary:hover:not(:disabled){transform:translateY(-1px);box-shadow:0 8px 18px rgba(37,99,235,.27)}.purchase-form-button-secondary{background:var(--card);border-color:var(--border);color:var(--text2)}.purchase-form-button-secondary:hover{background:var(--bg);border-color:var(--text3)}.purchase-form-button:focus-visible{outline:3px solid var(--blue-bg);outline-offset:2px}.purchase-button-icon{display:inline-flex;width:16px;height:16px}.purchase-button-icon svg{width:100%;height:100%;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}.purchase-form-button:disabled{opacity:.5;cursor:not-allowed;box-shadow:none}
