<script>
const purchaseProducts=<?php echo json_encode($products,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT); ?>;
const purchaseCurrency=<?php echo json_encode($currency); ?>;
const purchaseBatchPrefix=<?php echo json_encode($batchPrefix); ?>;
let purchaseItemIndex=0;
let purchaseCurrentTotal=0;
let purchasePaymentAmountEdited=false;
function escapePurchaseText(value){return String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));}
function addPurchaseItem(){const container=document.getElementById('purchaseItemRows');const index=purchaseItemIndex++;const options=purchaseProducts.map(product=>`<option value="${Number(product.id)}">${escapePurchaseText(product.name)} (${escapePurchaseText(product.sku)})</option>`).join('');const row=document.createElement('div');row.className='purchase-item-row';row.id='purchase-item-'+index;row.innerHTML=`<div class="product-field"><select name="product_ids[]" onchange="syncPurchaseProduct(${index})" required><option value="">Select product</option>${options}</select><small class="product-help"></small></div><input type="number" name="quantities[]" min=".0001" step=".0001" placeholder="Quantity" required oninput="calculatePurchaseTotal()"><input type="number" name="unit_costs[]" min="0" step=".0001" placeholder="Unit cost" required oninput="calculatePurchaseTotal()"><input type="number" name="unit_selling_prices[]" min="0" step=".0001" placeholder="Sale price" required><div class="expiry-field"><input class="expiry-input" type="date" name="expiry_dates[]" hidden><small class="expiry-help"></small></div><button type="button" class="purchase-remove-item" onclick="removePurchaseItem(${index})" aria-label="Remove product">&times;</button>`;container.appendChild(row);}
function syncPurchaseProduct(index){const row=document.getElementById('purchase-item-'+index);const product=purchaseProducts.find(item=>Number(item.id)===Number(row.querySelector('select').value));const expiry=row.querySelector('.expiry-input');const tracksExpiry=product&&Number(product.track_expiry)===1;expiry.hidden=!tracksExpiry;expiry.required=!!tracksExpiry;if(!tracksExpiry)expiry.value='';row.querySelector('.expiry-help').textContent=tracksExpiry?'Expiry date required':'';row.querySelector('.product-help').textContent=product&&Number(product.track_batches)===1?purchaseBatchPrefix+' batch number generated automatically':'';}
function removePurchaseItem(index){if(document.querySelectorAll('.purchase-item-row').length<=1){alert('A purchase must contain at least one product.');return;}document.getElementById('purchase-item-'+index)?.remove();calculatePurchaseTotal();}
function calculatePurchaseTotal(){let total=0;document.querySelectorAll('.purchase-item-row').forEach(row=>{total+=(parseFloat(row.querySelector('[name="quantities[]"]').value)||0)*(parseFloat(row.querySelector('[name="unit_costs[]"]').value)||0);});purchaseCurrentTotal=total;document.getElementById('purchaseTotal').textContent=total.toFixed(2)+' '+purchaseCurrency;const paymentAmount=document.getElementById('purchasePaymentAmount');paymentAmount.max=total>0?total.toFixed(4):'';if(!purchasePaymentAmountEdited&&document.querySelector('[name="settlement_type"]:checked')?.value==='PAID')paymentAmount.value=total>0?total.toFixed(2):'';document.getElementById('paymentAmountHint').textContent='Maximum due: '+total.toFixed(2)+' '+purchaseCurrency;updatePurchasePaymentBalance();}
function markPaymentAmountEdited(){purchasePaymentAmountEdited=true;updatePurchasePaymentBalance();}
function updatePurchasePaymentBalance(){const input=document.getElementById('purchasePaymentAmount');const paid=document.querySelector('[name="settlement_type"]:checked')?.value==='PAID';const amount=paid?(parseFloat(input.value)||0):0;const overpaid=paid&&amount>purchaseCurrentTotal+.00005;const remaining=Math.max(0,purchaseCurrentTotal-amount);input.setCustomValidity(overpaid?'Payment amount cannot be greater than the purchase total.':'');document.getElementById('purchaseRemainingBalance').textContent=remaining.toFixed(2)+' '+purchaseCurrency;document.getElementById('purchasePaymentWarning').hidden=!overpaid;document.getElementById('purchasePaymentPreview').classList.toggle('is-error',overpaid);}
function syncPurchaseType(){const type=document.querySelector('[name="purchase_type"]:checked')?.value||'';const direct=type==='DIRECT';const order=type==='PURCHASE_ORDER';const number=document.getElementById('purchaseNumber');const sequence=number.dataset.sequence;const generated=/^(DP|PO)-\d+$/.test(number.value)||number.value==='';if(generated)number.value=direct?'DP-'+sequence:(order?'PO-'+sequence:'');number.placeholder=direct?'DP-'+sequence:(order?'PO-'+sequence:'Choose a purchase method first');document.getElementById('purchaseNumberLabel').textContent=direct?'Direct Purchase Number':(order?'Purchase Order Number':'Purchase Number');document.getElementById('purchaseInformationTitle').textContent=direct?'Direct Purchase Information':(order?'Purchase Order Information':'Purchase Information');document.getElementById('purchaseInformationDescription').textContent=direct?'Supplier, receiving location, and direct purchase reference.':(order?'Supplier, future delivery location, and purchase order reference.':'Supplier, delivery location, and purchase reference.');document.getElementById('purchasePageEyebrow').textContent=direct?'Direct purchase workflow':(order?'Purchase order workflow':'New supplier purchase');document.getElementById('purchasePageDescription').textContent=direct?'Save once to create the purchase, receive every item, and update stock automatically.':(order?'Create a draft supplier order and receive it through the separate receiving process.':'First choose whether stock will be received immediately or through a separate purchase order process.');const methodStatus=document.getElementById('purchaseMethodStatus');methodStatus.textContent=direct?'Direct Purchase selected':(order?'Purchase Order selected':'Selection required');methodStatus.classList.toggle('is-selected',!!type);document.getElementById('purchaseWorkflowHelp').textContent=direct?'Saving automatically marks the purchase Received and updates stock.':(order?'The order will be saved as Draft and must be marked Ordered before receiving.':'Choose a purchase method above.');document.getElementById('purchaseActionTitle').textContent=direct?'Ready to record and receive this purchase?':(order?'Ready to create this purchase order?':'Choose a purchase method to continue');document.getElementById('purchaseActionDescription').textContent=direct?'All purchased quantities will be added to inventory immediately.':(order?'The purchase order will be saved as a draft for a separate receiving process.':'Your selected workflow determines what happens after this form is saved.');const button=document.getElementById('recordPurchaseButton');button.querySelector('.purchase-button-label').textContent=direct?'Record & Receive Purchase':(order?'Create Purchase Order':'Choose Purchase Method');button.disabled=!type||button.dataset.resourcesReady!=='1';}
function syncPurchasePayment(){const paid=document.querySelector('[name="settlement_type"]:checked')?.value==='PAID';const method=document.getElementById('purchasePaymentMethod').value;const paidFields=document.getElementById('paidPurchaseFields');const debtNote=document.getElementById('debtNote');const paymentAmount=document.getElementById('purchasePaymentAmount');const phoneField=document.getElementById('phonePaymentField');const bankFields=document.getElementById('bankPaymentFields');paidFields.hidden=!paid;debtNote.hidden=paid;paymentAmount.required=paid;if(paid&&!purchasePaymentAmountEdited)paymentAmount.value=purchaseCurrentTotal>0?purchaseCurrentTotal.toFixed(2):'';if(!paid)paymentAmount.setCustomValidity('');phoneField.hidden=!paid||method!=='MOBILE_MONEY';bankFields.hidden=!paid||method!=='BANK_TRANSFER';document.getElementById('paymentPhone').required=paid&&method==='MOBILE_MONEY';document.getElementById('paymentBankName').required=paid&&method==='BANK_TRANSFER';document.getElementById('paymentBankAccount').required=paid&&method==='BANK_TRANSFER';document.getElementById('paymentMethodNote').textContent=method==='CASH'?'Cash payments require no additional details.':method==='MOBILE_MONEY'?'Enter the telephone number used for payment.':'Enter both the bank name and account number.';updatePurchasePaymentBalance();}
document.getElementById('recordPurchaseForm').addEventListener('submit',function(){const button=document.getElementById('recordPurchaseButton');const direct=document.querySelector('[name="purchase_type"]:checked')?.value==='DIRECT';button.disabled=true;button.querySelector('.purchase-button-label').textContent=direct?'Saving Purchase...':'Creating Purchase Order...';});
addPurchaseItem();syncPurchasePayment();syncPurchaseType();
</script>

